// BEGIN PRODUCTION FEATURES
annotation { "Feature Type Name" : "NOMAD E Base" }
export const nomadEBase = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Show keep-outs and cable envelopes" }
        definition.showReserves is boolean;
    }
    {
        nomadEBuildBase(context, id, definition.showReserves);
        reportFeatureInfo(context, id, "NOMAD E Base: Round C base V0.1 (D-007 PROPOSED). All sizes are nomad.yaml " ~
                    "working values (provisional); ENV_* are envelopes, not components.");
    }, { "showReserves" : true });

annotation { "Feature Type Name" : "NOMAD E Service" }
export const nomadEService = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Show representative fasteners" }
        definition.showFasteners is boolean;
    }
    {
        const r = nomadEBuildService(context, id, definition.showFasteners);
        reportFeatureInfo(context, id, "NOMAD E Service: service panel, battery door, port panels (Round C). Fasteners " ~
                    "are representative M3 heads, not a fastener selection. " ~ r.note);
    }, { "showFasteners" : true });

annotation { "Feature Type Name" : "NOMAD E Lid" }
export const nomadELid = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Show keep-outs and cable envelopes" }
        definition.showReserves is boolean;
        annotation { "Name" : "Preview lid angle (keep 0 for the Assembly)" }
        isAngle(definition.lidAngle, NOMAD_E_LID_ANGLE_BOUNDS);
        annotation { "Name" : "Preview right cassette extension (0 stowed, 1 deployed)" }
        isReal(definition.extR, NOMAD_E_EXT_BOUNDS);
        annotation { "Name" : "Preview left cassette extension (0 stowed, 1 deployed)" }
        isReal(definition.extL, NOMAD_E_EXT_BOUNDS);
        annotation { "Name" : "Preview right cassette tilt" }
        isAngle(definition.tiltR, NOMAD_E_TILT_BOUNDS);
        annotation { "Name" : "Preview left cassette tilt" }
        isAngle(definition.tiltL, NOMAD_E_TILT_BOUNDS);
    }
    {
        const r = nomadEBuildLid(context, id, definition);
        reportFeatureInfo(context, id, "NOMAD E Lid: class A lid " ~ toString(roundToPrecision(LID_THICKNESS / millimeter, 1)) ~
                    " mm, PROVISIONAL - PENDING P0.2 PHYSICAL VALIDATION. Solar = B.1 V1 + fixes + D-009 index lock (11 x 15 deg; " ~
                    "+-80 hard stops NOT packaged); hinge representative. " ~ r.note);
    }, { "showReserves" : true, "lidAngle" : 0 * degree, "extR" : 0, "extL" : 0, "tiltR" : 0 * degree, "tiltL" : 0 * degree });
// END PRODUCTION FEATURES

