export const NOMAD_E_ATTRIBUTE = "nomadE";

function nomadEColor(key is string) returns Color
{
    const c = {
            "structure" : color(0.24, 0.25, 0.27, 1),
            "tray" : color(0.38, 0.39, 0.42, 1),
            "service" : color(0.52, 0.47, 0.42, 1),
            "input" : color(0.10, 0.10, 0.11, 1),
            "inputProv" : color(0.30, 0.30, 0.35, 1),
            "electronics" : color(0.82, 0.84, 0.80, 0.6),
            "battery" : color(0.90, 0.80, 0.45, 0.55),
            "hardware" : color(0.68, 0.70, 0.74, 1),
            "stainless" : color(0.80, 0.82, 0.86, 1),
            "H" : color(0.85, 0.2, 0.2, 0.3), "K" : color(0.95, 0.6, 0.1, 0.3), "C" : color(0.2, 0.7, 0.3, 0.35),
            "W" : color(0.6, 0.3, 0.8, 0.35), "X" : color(0.95, 0.85, 0.1, 0.3),
            "display" : color(0.04, 0.04, 0.05, 1),
            "shell" : color(0.20, 0.21, 0.23, 1),
            "rail" : color(0.56, 0.58, 0.61, 1),
            "carriage" : color(0.33, 0.35, 0.39, 1),
            "bracket" : color(0.46, 0.42, 0.34, 1),
            "cassette" : color(0.15, 0.22, 0.38, 1),
            "hinge" : color(0.64, 0.66, 0.70, 1)
        };
    return c[key];
}

// Round C layout part -> [displayed name, palette key, feature group]. Groups: "base" (NOMAD E Base),
// "service" (NOMAD E Service). Keep-outs / cable envelopes (categories H K C W X) are "reserve" parts of
// NOMAD E Base, keep their layout names and follow the "Show keep-outs" toggle.
const NOMAD_E_BASE_MAP = {
        "BASE_SHELL" : ["BASE_SHELL", "structure", "base"],
        "KEYBOARD_TRAY" : ["KEYBOARD_TRAY", "tray", "base"],
        "TRACKPAD_TRAY" : ["TRACKPAD_TRAY", "tray", "base"],
        "COMPUTE_SLED" : ["COMPUTE_SLED (Pi mounting plate)", "tray", "base"],
        "ENV_KEYBOARD" : ["ENV_KEYBOARD [provisional 280x105x8]", "input", "base"],
        "ENV_TRACKPAD" : ["ENV_TRACKPAD [PROVISIONAL - module not selected]", "inputProv", "base"],
        "ENV_PI_STACK" : ["ENV_PI5_BOARD_COOLER [PROVISIONAL]", "electronics", "base"],
        "ENV_COMPUTE_POWER" : ["ENV_COMPUTE_POWER [PROVISIONAL]", "electronics", "base"],
        "ENV_POWER_ELECTRONICS" : ["ENV_POWER_ELECTRONICS [PROVISIONAL]", "electronics", "base"],
        "ENV_BATTERY_BAY" : ["ENV_BATTERY_BAY [RESERVE - no pack chosen]", "battery", "base"],
        "ENV_GNSS_MODULE" : ["ENV_GNSS_MODULE [PROVISIONAL - separate module]", "electronics", "base"],
        "SERVICE_PANEL_MAIN" : ["SERVICE_PANEL_MAIN", "service", "service"],
        "BATTERY_DOOR" : ["BATTERY_DOOR", "service", "service"],
        "PORT_PANEL_MAIN" : ["PORT_PANEL_MAIN", "service", "service"],
        "PORT_PANEL_AUX" : ["PORT_PANEL_AUX", "service", "service"],
        "PANEL_STANDOFF_L" : ["PANEL_STANDOFF_L", "service", "service"],
        "PANEL_STANDOFF_R" : ["PANEL_STANDOFF_R", "service", "service"]
    };

// Representative M3 fastener head (not a selection) and the counterbore it sits in (service panel / door).
const NOMAD_E_HEAD_D = 5.5 * millimeter;
const NOMAD_E_HEAD_H = 1.7 * millimeter;
const NOMAD_E_CBORE_D = 6.2 * millimeter;
const NOMAD_E_CBORE_H = 1.9 * millimeter;
const NOMAD_E_TOL = 1e-6 * millimeter;

function nomadETag(context is Context, body is Query, name is string, key is string)
{
    setProperty(context, { "entities" : body, "propertyType" : PropertyType.NAME, "value" : name });
    setProperty(context, { "entities" : body, "propertyType" : PropertyType.APPEARANCE, "value" : nomadEColor(key) });
    setAttribute(context, { "entities" : body, "name" : NOMAD_E_ATTRIBUTE, "attribute" : name });
}

function nomadEGroup(spec is array) returns string
{
    const m = NOMAD_E_BASE_MAP[spec[0]];
    return m == undefined ? "reserve" : m[2];
}

// One named solid = union of layout primitives (["box", label, x0, y0, z0, x1, y1, z1] | ["cyl", label, cx, cy, d, z0, z1]).
function nomadEPrims(context is Context, pid is Id, prims is array) returns Query
{
    for (var j = 0; j < size(prims); j += 1)
    {
        const q = prims[j];
        if (q[0] == "box")
            fCuboid(context, pid + ("p" ~ j), { "corner1" : vector(q[2], q[3], q[4]), "corner2" : vector(q[5], q[6], q[7]) });
        else
            fCylinder(context, pid + ("p" ~ j), { "bottomCenter" : vector(q[2], q[3], q[5]),
                        "topCenter" : vector(q[2], q[3], q[6]), "radius" : q[4] / 2 });
    }
    if (size(prims) > 1)
        opBoolean(context, pid + "union", { "tools" : qCreatedBy(pid, EntityType.BODY), "operationType" : BooleanOperationType.UNION });
    return qCreatedBy(pid, EntityType.BODY);
}

// Hinge axis frame shared by the base and lid connectors: origin on the D-006 axis at the centreline,
// Z along -X (a positive angle raises the lid's free edge), X along +Y. Angle 0 = closed.
export function nomadEHingeFrame() returns CoordSystem
{
    return coordSystem(vector(0 * millimeter, BODY_DEPTH - HINGE_AXIS_OFFSET, BODY_HEIGHT + HINGE_AXIS_HEIGHT),
            vector(0, 1, 0), vector(-1, 0, 0));
}

// ================= E1: base =================

// Builds the base structure, input envelopes, electronics envelopes and (optionally) keep-outs / cable
// envelopes. The Round C ENV_PI_STACK envelope is shown as two parts: board + cooler, and the top
// PI_HAT_ZONE_HEIGHT as the M.2 HAT+ / NVMe zone (visual subdivision only). Returns layout name -> body;
// "ENV_PI_STACK" maps to the union of both halves. Adds MC_HINGE_BASE owned by BASE_SHELL.
export function nomadEBuildBase(context is Context, id is Id, withReserves is boolean) returns map
{
    var parts = {};
    const table = nomadBaseV01Parts();
    for (var i = 0; i < size(table); i += 1)
    {
        const spec = table[i];
        const group = nomadEGroup(spec);
        if (group == "service" || (group == "reserve" && !withReserves))
            continue;
        const pid = id + ("part" ~ i);
        if (spec[0] == "ENV_PI_STACK")
        {
            const q = spec[2][0];
            const zs = q[7] - PI_HAT_ZONE_HEIGHT;
            fCuboid(context, pid + "lo", { "corner1" : vector(q[2], q[3], q[4]), "corner2" : vector(q[5], q[6], zs) });
            fCuboid(context, pid + "hi", { "corner1" : vector(q[2], q[3], zs), "corner2" : vector(q[5], q[6], q[7]) });
            const lo = qCreatedBy(pid + "lo", EntityType.BODY);
            const hi = qCreatedBy(pid + "hi", EntityType.BODY);
            nomadETag(context, lo, NOMAD_E_BASE_MAP["ENV_PI_STACK"][0], "electronics");
            nomadETag(context, hi, "ENV_NVME_HAT [PROVISIONAL - zone of the Pi stack envelope]", "electronics");
            parts["ENV_PI5_BOARD_COOLER"] = lo;
            parts["ENV_NVME_HAT"] = hi;
            parts["ENV_PI_STACK"] = qUnion([lo, hi]);
            continue;
        }
        const body = nomadEPrims(context, pid, spec[2]);
        if (group == "reserve")
            nomadETag(context, body, spec[0], spec[1]);
        else
            nomadETag(context, body, NOMAD_E_BASE_MAP[spec[0]][0], NOMAD_E_BASE_MAP[spec[0]][1]);
        parts[spec[0]] = body;
    }
    opMateConnector(context, id + "mcHingeBase", { "coordSystem" : nomadEHingeFrame(), "owner" : parts["BASE_SHELL"] });
    parts["MC_HINGE_BASE"] = qCreatedBy(id + "mcHingeBase", EntityType.BODY);
    return parts;
}

// ================= E1: service =================

// Screw points from the Round C layout: panel/door bosses (cylinders starting at the panel top, BV_IZ0),
// the two panel standoffs, and the compute-sled bosses (starting at the sled top, BV_SLZ1).
export function nomadEScrewPoints() returns map
{
    var panel = [];
    var sled = [];
    const table = nomadBaseV01Parts();
    for (var i = 0; i < size(table); i += 1)
    {
        const spec = table[i];
        if (spec[0] != "BASE_SHELL" && spec[0] != "PANEL_STANDOFF_L" && spec[0] != "PANEL_STANDOFF_R")
            continue;
        for (var q in spec[2])
        {
            if (q[0] != "cyl")
                continue;
            if (abs(q[5] - BV_IZ0) < NOMAD_E_TOL)
                panel = append(panel, [q[2], q[3]]);
            else if (abs(q[5] - BV_SLZ1) < NOMAD_E_TOL)
                sled = append(sled, [q[2], q[3]]);
        }
    }
    return { "panel" : panel, "sled" : sled };
}

function nomadEInBoxes(prims is array, p is array) returns boolean
{
    for (var q in prims)
    {
        if (q[0] == "box" && p[0] >= q[2] - NOMAD_E_TOL && p[0] <= q[5] + NOMAD_E_TOL &&
            p[1] >= q[3] - NOMAD_E_TOL && p[1] <= q[6] + NOMAD_E_TOL)
            return true;
    }
    return false;
}

// Builds the service parts; with fasteners, cuts a counterbore in the panel / door under each panel screw
// and adds a representative head there, plus heads under the compute sled at its bosses (the sled screws
// up into them; Round C). Heads are NOT moved to avoid anything: a clash is a finding. Returns
// name -> body plus "fasteners" (array), "sledHeads" (array) and a "note".
export function nomadEBuildService(context is Context, id is Id, withFasteners is boolean) returns map
{
    var parts = {};
    var prims = {};
    const table = nomadBaseV01Parts();
    for (var i = 0; i < size(table); i += 1)
    {
        const spec = table[i];
        if (nomadEGroup(spec) != "service")
            continue;
        const body = nomadEPrims(context, id + ("part" ~ i), spec[2]);
        nomadETag(context, body, NOMAD_E_BASE_MAP[spec[0]][0], NOMAD_E_BASE_MAP[spec[0]][1]);
        parts[spec[0]] = body;
        prims[spec[0]] = spec[2];
    }
    var fasteners = [];
    var sledHeads = [];
    if (!withFasteners)
        return mergeMaps(parts, { "fasteners" : fasteners, "sledHeads" : sledHeads, "note" : "Fasteners hidden." });
    const pts = nomadEScrewPoints();
    var counts = { "SERVICE_PANEL_MAIN" : 0, "BATTERY_DOOR" : 0 };
    for (var k = 0; k < size(pts.panel); k += 1)
    {
        const p = pts.panel[k];
        var owner = undefined;
        for (var name in ["SERVICE_PANEL_MAIN", "BATTERY_DOOR"])
        {
            if (nomadEInBoxes(prims[name], p))
                owner = name;
        }
        if (owner == undefined)
            continue;
        const cid = id + ("cbore" ~ k);
        fCylinder(context, cid, { "bottomCenter" : vector(p[0], p[1], -0.1 * millimeter),
                    "topCenter" : vector(p[0], p[1], NOMAD_E_CBORE_H), "radius" : NOMAD_E_CBORE_D / 2 });
        opBoolean(context, id + ("cut" ~ k), { "tools" : qCreatedBy(cid, EntityType.BODY), "targets" : parts[owner],
                    "operationType" : BooleanOperationType.SUBTRACTION });
        const hid = id + ("head" ~ k);
        const z0 = (NOMAD_E_CBORE_H - NOMAD_E_HEAD_H) / 2;
        fCylinder(context, hid, { "bottomCenter" : vector(p[0], p[1], z0), "topCenter" : vector(p[0], p[1], z0 + NOMAD_E_HEAD_H),
                    "radius" : NOMAD_E_HEAD_D / 2 });
        counts[owner] += 1;
        const head = qCreatedBy(hid, EntityType.BODY);
        nomadETag(context, head, "FASTENER_M3 [representative] " ~ (owner == "BATTERY_DOOR" ? "DOOR " : "PANEL ") ~ counts[owner], "hardware");
        fasteners = append(fasteners, head);
    }
    for (var k = 0; k < size(pts.sled); k += 1)
    {
        const p = pts.sled[k];
        const hid = id + ("sledHead" ~ k);
        fCylinder(context, hid, { "bottomCenter" : vector(p[0], p[1], BV_SLZ0 - NOMAD_E_HEAD_H),
                    "topCenter" : vector(p[0], p[1], BV_SLZ0), "radius" : NOMAD_E_HEAD_D / 2 });
        const head = qCreatedBy(hid, EntityType.BODY);
        nomadETag(context, head, "FASTENER_M3 [representative] SLED " ~ (k + 1), "hardware");
        fasteners = append(fasteners, head);
        sledHeads = append(sledHeads, head);
    }
    return mergeMaps(parts, { "fasteners" : fasteners, "sledHeads" : sledHeads,
                "note" : toString(counts.SERVICE_PANEL_MAIN) ~ " panel + " ~ toString(counts.BATTERY_DOOR) ~ " door + " ~
                toString(size(sledHeads)) ~ " sled screws." });
}

// ================= E2: lid, solar mechanism, hinge =================

// Visualization pose bounds (dialog only; the Assembly mates carry the real motion). 135 = LID_ANGLE_MAX working,
// 75 = SOLAR_ROTATION_LIMIT max (provisional).
const NOMAD_E_LID_ANGLE_BOUNDS = { (degree) : [0, 0, 135] } as AngleBoundSpec;
const NOMAD_E_TILT_BOUNDS = { (degree) : [-75, 0, 75] } as AngleBoundSpec;
const NOMAD_E_EXT_BOUNDS = { (unitless) : [0, 0, 1] } as RealBoundSpec;

// One layout primitive as a solid: "box" (x0, y0, z0, x1, y1, z1), "cylx" (cy, cz, d, x0, x1: cylinder along X) or
// "prof" (x0, x1, edges: one closed Y-Z loop of ["L", y0, z0, y1, z1] / ["A", cy, cz, r, a0, a1] edges extruded along X;
// used by the D-009 index lock for the carriage slab, the double-D hub-pin keys and the stainless plates).
function nomadELidPrim(context is Context, pid is Id, q is array)
{
    if (q[0] == "box")
        fCuboid(context, pid, { "corner1" : vector(q[2], q[3], q[4]), "corner2" : vector(q[5], q[6], q[7]) });
    else if (q[0] == "cylx")
        fCylinder(context, pid, { "bottomCenter" : vector(q[5], q[2], q[3]), "topCenter" : vector(q[6], q[2], q[3]),
                    "radius" : q[4] / 2 });
    else
    {
        const sk = newSketchOnPlane(context, pid + "sk", { "sketchPlane" : plane(vector(q[2], 0 * millimeter, 0 * millimeter),
                        vector(1, 0, 0), vector(0, 1, 0)) });
        for (var k = 0; k < size(q[4]); k += 1)
        {
            const e = q[4][k];
            if (e[0] == "L")
                skLineSegment(sk, "e" ~ k, { "start" : vector(e[1], e[2]), "end" : vector(e[3], e[4]) });
            else
            {
                const am = (e[4] + e[5]) / 2;
                skArc(sk, "e" ~ k, { "start" : vector(e[1] + e[3] * cos(e[4]), e[2] + e[3] * sin(e[4])),
                            "mid" : vector(e[1] + e[3] * cos(am), e[2] + e[3] * sin(am)),
                            "end" : vector(e[1] + e[3] * cos(e[5]), e[2] + e[3] * sin(e[5])) });
            }
        }
        skSolve(sk);
        opExtrude(context, pid + "ex", { "entities" : qSketchRegion(pid + "sk"), "direction" : vector(1, 0, 0),
                    "endBound" : BoundingType.BLIND, "endDepth" : q[3] - q[2] });
        opDeleteBodies(context, pid + "del", { "entities" : qCreatedBy(pid + "sk", EntityType.BODY) });
    }
}

// Builds one layout primitive list as a single solid.
function nomadEPrimsLid(context is Context, pid is Id, prims is array) returns Query
{
    for (var j = 0; j < size(prims); j += 1)
        nomadELidPrim(context, pid + ("p" ~ j), prims[j]);
    if (size(prims) > 1)
        opBoolean(context, pid + "union", { "tools" : qCreatedBy(pid, EntityType.BODY), "operationType" : BooleanOperationType.UNION });
    return qCreatedBy(pid, EntityType.BODY);
}

function nomadEIsReserve(key is string) returns boolean
{
    return key == "C" || key == "W" || key == "K";
}

// Builds the class A lid, both solar sides (B.1 V1 + fixes), both hinges and the lid keep-outs in the closed / stowed
// pose; cuts the hinge pockets into BASE_SHELL when the NOMAD E Base part exists; adds the mate connectors; then applies
// the optional visualization pose (tilt about the hub axis, slide along X, lid rotation about the D-006 axis).
// Returns { "parts" : name -> body, "mc" : name -> connector, "note" : string }.
export function nomadEBuildLid(context is Context, id is Id, definition is map) returns map
{
    var parts = {};
    var groups = {};
    const table = nomadELidParts();
    for (var i = 0; i < size(table); i += 1)
    {
        const spec = table[i];
        if (!definition.showReserves && nomadEIsReserve(spec[3]))
            continue;
        const body = nomadEPrimsLid(context, id + ("lid" ~ i), spec[4]);
        const subs = spec[5];
        if (size(subs) > 0)
        {
            for (var j = 0; j < size(subs); j += 1)
                nomadELidPrim(context, id + ("lidSub" ~ i) + ("t" ~ j), subs[j]);
            opBoolean(context, id + ("lidCut" ~ i), { "tools" : qCreatedBy(id + ("lidSub" ~ i), EntityType.BODY), "targets" : body,
                        "operationType" : BooleanOperationType.SUBTRACTION });
        }
        nomadETag(context, body, spec[1], spec[3]);
        parts[spec[0]] = body;
        groups[spec[2]] = append(groups[spec[2]] == undefined ? [] : groups[spec[2]], body);
    }
    // hinge pockets in the E1 base shell (only when that part exists in this Part Studio; "cutPockets" : false skips them,
    // used by the scratch harness when it builds extra posed copies against the same shell)
    const shell = qHasAttributeWithValue(qEverything(EntityType.BODY), NOMAD_E_ATTRIBUTE, "BASE_SHELL");
    var pocketed = false;
    if (definition.cutPockets != false && size(evaluateQuery(context, shell)) > 0)
    {
        const pockets = nomadELidBasePockets();
        for (var j = 0; j < size(pockets); j += 1)
        {
            const q = pockets[j];
            fCuboid(context, id + "pocket" + ("t" ~ j), { "corner1" : vector(q[2], q[3], q[4]), "corner2" : vector(q[5], q[6], q[7]) });
        }
        opBoolean(context, id + "pocketCut", { "tools" : qCreatedBy(id + "pocket", EntityType.BODY), "targets" : shell,
                    "operationType" : BooleanOperationType.SUBTRACTION });
        pocketed = true;
    }
    // mate connectors (owned: they move with their parts in the Assembly)
    var mc = {};
    const conns = nomadELidConnectors();
    for (var k = 0; k < size(conns); k += 1)
    {
        const c = conns[k];
        opMateConnector(context, id + ("mc" ~ k), { "coordSystem" : coordSystem(vector(c[2][0], c[2][1], c[2][2]),
                        vector(c[3][0], c[3][1], c[3][2]), vector(c[4][0], c[4][1], c[4][2])), "owner" : parts[c[1]] });
        mc[c[0]] = qCreatedBy(id + ("mc" ~ k), EntityType.BODY);
    }
    // visualization pose: tilt (about the stowed hub axis), slide, then lid rotation
    var moving = [];
    for (var sd in [["R", 1, definition.extR, definition.tiltR, LE_HYR], ["L", -1, definition.extL, definition.tiltL, LE_HYL]])
    {
        const car = qUnion(concatenateArrays([groups["car" ~ sd[0]] == undefined ? [] : groups["car" ~ sd[0]],
                                [mc["MC_CARRIAGE_" ~ sd[0]], mc["MC_HUB_" ~ sd[0]]]]));
        const cas = qUnion(concatenateArrays([groups["cas" ~ sd[0]], [mc["MC_CASSETTE_" ~ sd[0]]]]));
        if (abs(sd[3]) > 1e-9 * degree)
            opTransform(context, id + ("tilt" ~ sd[0]), { "bodies" : cas,
                        "transform" : rotationAround(line(vector(sd[1] * LE_XI, sd[4], LE_HZ), vector(sd[1], 0, 0)), sd[3]) });
        if (abs(sd[2]) > 1e-9)
            opTransform(context, id + ("slide" ~ sd[0]), { "bodies" : qUnion([car, cas]),
                        "transform" : transform(vector(sd[1] * sd[2] * SOLAR_SLIDE_TRAVEL, 0 * millimeter, 0 * millimeter)) });
        moving = concatenateArrays([moving, [car, cas]]);
    }
    if (abs(definition.lidAngle) > 1e-9 * degree)
    {
        var lidSide = concatenateArrays([groups["lid"], moving]);
        for (var n in ["MC_HINGE_LID", "MC_RAIL_R", "MC_RAIL_L"])
            lidSide = append(lidSide, mc[n]);
        opTransform(context, id + "lidPose", { "bodies" : qUnion(lidSide),
                    "transform" : rotationAround(line(vector(0 * millimeter, LE_HAY, LE_HAZ), vector(-1, 0, 0)), definition.lidAngle) });
    }
    return { "parts" : parts, "mc" : mc,
            "note" : (pocketed ? "Hinge pockets cut in BASE_SHELL." : "BASE_SHELL not found: hinge pockets not cut.") ~
            " Pose: lid " ~ toString(roundToPrecision(definition.lidAngle / degree, 1)) ~ " deg, R " ~ toString(definition.extR) ~
            " / L " ~ toString(definition.extL) ~ " extended." };
}
